import 'dotenv/config'; import express from 'express'; import cors from 'cors'; import morgan from 'morgan'; import path from 'path'; import {fileURLToPath} from 'url'; import {connectDB} from './config/db.js'; import authRoutes from './routes/auth.js'; import bookRoutes from './routes/books.js'; import memberRoutes from './routes/members.js'; import loanRoutes from './routes/loans.js'; import miscRoutes from './routes/misc.js'; import portalRoutes from './routes/portal.js'; import {requireAdmin} from './middleware/auth.js'; import {requireAuth} from './middleware/auth.js';
const app=express();const __filename=fileURLToPath(import.meta.url);const __dirname=path.dirname(__filename);app.use(cors({origin:process.env.CLIENT_URL||'http://localhost:5173'}));app.use(express.json());app.use(morgan('dev'));app.get('/api/health',(req,res)=>res.json({ok:true}));app.use('/api/auth',authRoutes);app.use('/api',requireAuth);app.use('/api/portal',portalRoutes);app.use('/api/books',requireAdmin,bookRoutes);app.use('/api/members',requireAdmin,memberRoutes);app.use('/api/loans',loanRoutes);app.use('/api',requireAdmin,miscRoutes);const clientDist=path.join(__dirname,'../client/dist');app.use(express.static(clientDist));app.get('*',(req,res,next)=>{if(req.path.startsWith('/api/'))return next();res.sendFile(path.join(clientDist,'index.html'),err=>err&&res.status(404).send('Frontend build not found. Run npm run build.'));});app.use((err,req,res,next)=>{console.error(err);if(err?.code===11000)return res.status(409).json({message:'A record with that unique value already exists'});if(err?.name==='ValidationError')return res.status(400).json({message:Object.values(err.errors).map(e=>e.message).join(', ')});res.status(500).json({message:err.message||'Server error'});});const port=Number(process.env.PORT||5000);connectDB().then(()=>app.listen(port,()=>console.log(`API running on http://localhost:${port}`))).catch(err=>{console.error('MongoDB connection failed:',err.message);process.exit(1);});
